        if (sum <= budget) {
            best = std::max(best, sum);
            ++i;
        } else {
            --j;
        }
    }
    if (best >= 0) {
        std::cout << "spend " << best << '\n';
    } else {
        std::cout << "no pair" << '\n';
    }
    return 0;
}

steps.body:
A window is the stretch from `left` to `right`. To find the longest stretch that obeys a rule, move `right` one step every pass to grow the window, and whenever the window breaks the rule, move `left` until it holds again. Each index enters once and leaves once, so the whole scan is O(n).

For the longest substring with no repeated letter, an `unordered_map` counts the letters inside the window:

```cpp
std::string s = "abcabcbb";
std::unordered_map<char, int> count;
int left = 0;
int best = 0;
for (int right = 0; right < static_cast<int>(s.size()); ++right) {
    ++count[s[right]];
    while (count[s[right]] > 1) {   // a repeat: shrink from the left
        --count[s[left]];
        ++left;
    }
    best = std::max(best, right - left + 1);
}
std::cout << best << '\n';   // 3, "abc"
```

The window's length is `right - left + 1`. Only the letter that just came in can be repeated, so the `while` checks that one. The same shape works for any rule you can update one item at a time, like a running sum that must stay within a budget: add as `right` moves, subtract as `left` moves. It needs the rule to get easier as the window shrinks, which holds for sums of positive numbers but not when values can be negative.

example.code:
#include <iostream>
#include <string>
#include <unordered_map>

int main() {
    int q = 0;
    std::cin >> q;
    for (int t = 0; t < q; ++t) {
        std::string s;
        std::cin >> s;
        std::unordered_map<char, int> count;
        int left = 0;
        int best = 0;
        int bestStart = 0;
        for (int right = 0; right < static_cast<int>(s.size()); ++right) {
            ++count[s[right]];
            while (count[s[right]] > 1) {
                --count[s[left]];
                ++left;
            }
            if (right - left + 1 > best) {
                best = right - left + 1;
                bestStart = left;
            }
        }
        std::cout << s << ": " << best << ' ' << s.substr(bestStart, best) << '\n';
    }
    return 0;
}

