#include <iostream>
#include <string>
#include <vector>

// The first index where text holds an anagram of code, or -1.
int firstAnagram(const std::string& text, const std::string& code) {
    std::vector<int> need(26, 0);
    std::vector<int> have(26, 0);
    for (char c : code) {
        ++need[c - 'a'];
    }
    int m = static_cast<int>(code.size());
    for (int i = 0; i < static_cast<int>(text.size()); ++i) {
        ++have[text[i] - 'a'];
        if (i >= m) {
            --have[text[i - m] - 'a'];
        }
        if (have == need) {
            return i - m + 1;
        }
    }
    return -1;
}

int main() {
    int q = 0;
    std::cin >> q;
    for (int t = 0; t < q; ++t) {
        std::string text;
        std::string code;
        std::cin >> text >> code;
